-- READ ONLY: 006 + 007 installation, no goal save or restart. Dedicated TMSA / DRYBMS only.
begin transaction read only;
set local statement_timeout='15s';
with functions as (select p.*,n.nspname from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace), checks as (
select 'exact_four_rpc_overloads' name,(select count(*) from functions where nspname='public' and proname='compliance_rpc')=4 ok
 union all select 'legacy_four_unchanged',exists(select 1 from functions where oid=to_regprocedure('public.compliance_rpc(text,text,text,jsonb)') and prosecdef and md5(replace(prosrc,E'\r\n',E'\n'))='999bb75b6d31297eeba8a5090ccb6ee2')
 union all select 'legacy_five_boolean_unchanged',exists(select 1 from functions where oid=to_regprocedure('public.compliance_rpc(text,text,text,jsonb,boolean)') and prosecdef and md5(replace(prosrc,E'\r\n',E'\n'))='63e2634760cdf3bd465726d7e2128320')
 union all select 'legacy_six_boolean_unchanged',exists(select 1 from functions where oid=to_regprocedure('public.compliance_rpc(text,text,text,jsonb,boolean,boolean)') and prosecdef and md5(replace(prosrc,E'\r\n',E'\n'))='8e071416d849b87785a6eafd47669d8b')
 union all select 'legacy_dispatch_unchanged',exists(select 1 from functions where oid=to_regprocedure('compliance_private.dispatch(text,text,text,jsonb)') and prosecdef and md5(replace(prosrc,E'\r\n',E'\n'))='8cdfdd4c2952564ff8b46f580625596e')
 union all select 'original_validator_preserved',exists(select 1 from functions where oid=to_regprocedure('compliance_private.validate_record_before_shared_targets(text,jsonb,jsonb,text,jsonb)') and prosecdef and md5(replace(prosrc,E'\r\n',E'\n'))='037cfe64cf3e317605dbc4851d8553f4')
 union all select 'goal_validator_guard',exists(select 1 from functions where oid=to_regprocedure('compliance_private.validate_record(text,jsonb,jsonb,text,jsonb)') and prosecdef and md5(replace(prosrc,E'\r\n',E'\n'))='7998f089736bd984cddd7e940672a143')
 union all select 'goal_save_exact',exists(select 1 from functions where oid=to_regprocedure('compliance_private.save_shared_targets(text,text,jsonb)') and prosecdef and md5(replace(prosrc,E'\r\n',E'\n'))='7b439083bdedfa33d78c11f17f880bc9')
 union all select 'goal_claim_exact',exists(select 1 from functions where oid=to_regprocedure('compliance_private.claim_shared_targets(text,text,jsonb)') and prosecdef and md5(replace(prosrc,E'\r\n',E'\n'))='6a95ef46f5e69f1c29964c6027de73b7')
 union all select 'restart_helper_unchanged',exists(select 1 from functions where oid=to_regprocedure('compliance_private.restart_updates(text,text,jsonb)') and prosecdef and md5(replace(prosrc,E'\r\n',E'\n'))='47fbae83d036de80c3fc9b44e24e9348')
 union all select 'shared_route_exact',exists(select 1 from functions where oid=to_regprocedure('public.compliance_rpc(text,text,text,jsonb,text)') and prosecdef and md5(replace(prosrc,E'\r\n',E'\n'))='79d92bdca3a86f1891f91effd04653ac')
 union all select 'shared_route_definer_budget',exists(select 1 from functions where oid=to_regprocedure('public.compliance_rpc(text,text,text,jsonb,text)') and proconfig=array['search_path=""','statement_timeout=15s'] and proargnames=array['p_action','p_session','p_client_id','p_payload','p_sync_mode'])
 union all select 'helpers_empty_search_path',not exists(select 1 from functions where oid=any(array[to_regprocedure('compliance_private.save_shared_targets(text,text,jsonb)'),to_regprocedure('compliance_private.claim_shared_targets(text,text,jsonb)'),to_regprocedure('compliance_private.validate_record_before_shared_targets(text,jsonb,jsonb,text,jsonb)')]) and proconfig is distinct from array['search_path=""'])
 union all select 'helpers_matching_owner',not exists(select 1 from functions where oid=any(array[to_regprocedure('compliance_private.save_shared_targets(text,text,jsonb)'),to_regprocedure('compliance_private.claim_shared_targets(text,text,jsonb)'),to_regprocedure('compliance_private.validate_record_before_shared_targets(text,jsonb,jsonb,text,jsonb)')]) and proowner<>(select proowner from functions where oid=to_regprocedure('public.compliance_rpc(text,text,text,jsonb)')))
 union all select 'helpers_no_other_execute',not exists(select 1 from functions p,lateral pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a where p.oid=any(array[to_regprocedure('compliance_private.save_shared_targets(text,text,jsonb)'),to_regprocedure('compliance_private.claim_shared_targets(text,text,jsonb)'),to_regprocedure('compliance_private.validate_record_before_shared_targets(text,jsonb,jsonb,text,jsonb)')]) and a.grantee<>p.proowner and a.privilege_type='EXECUTE')
 union all select 'public_route_anon_allowed',pg_catalog.has_function_privilege('anon',to_regprocedure('public.compliance_rpc(text,text,text,jsonb,text)'),'EXECUTE')
 union all select 'public_route_no_public_execute',not exists(select 1 from functions p,lateral pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a where p.oid=to_regprocedure('public.compliance_rpc(text,text,text,jsonb,text)') and a.grantee=0 and a.privilege_type='EXECUTE')
 union all select 'private_schema_denied',not pg_catalog.has_schema_privilege('anon','compliance_private','USAGE')
 union all select 'private_tables_rls_anon_denied',not exists(select 1 from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname='compliance_private' and c.relkind='r' and (not c.relrowsecurity or pg_catalog.has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE')))
 union all select 'initialized',(select initialized from compliance_private.control where singleton)
 union all select 'imported',(select imported from compliance_private.control where singleton)
 union all select 'unique_active_owner',(select count(*) from compliance_private.records where kind='person' and body->'active'='true'::jsonb and body->>'role'='owner')=1
)
select jsonb_build_object('status',case when bool_and(coalesce(ok,false)) then 'PASS_SHARED_TARGETS_INSTALL_ONLY' else 'FAIL_SHARED_TARGETS_INSTALL' end,'checks',jsonb_object_agg(name,coalesce(ok,false)),'checkCount',count(*),'initialized',(select initialized from compliance_private.control where singleton),'imported',(select imported from compliance_private.control where singleton),'activeOwnerCount',(select count(*) from compliance_private.records where kind='person' and body->'active'='true'::jsonb and body->>'role'='owner'),'meaning','Catalog-only installation proof. No target save, restart or hosted UI acceptance performed.') shared_targets_readback from checks;
rollback;
